package com.example.zejioscafese.pos.ui

import android.view.LayoutInflater
import android.view.ViewGroup
import androidx.recyclerview.widget.DiffUtil
import androidx.recyclerview.widget.ListAdapter
import androidx.recyclerview.widget.RecyclerView
import com.example.zejioscafese.R
import com.example.zejioscafese.databinding.ItemProductBinding
import com.example.zejioscafese.pos.data.model.Product
import coil.load

class ProductAdapter(
    private val onProductClick: (Product) -> Unit
) : ListAdapter<Product, ProductAdapter.ProductViewHolder>(DiffCallback) {

    override fun onBindViewHolder(holder: ProductViewHolder, position: Int) {
        holder.bind(getItem(position))
    }

    class ProductViewHolder(
        private val binding: ItemProductBinding,
        private val onProductClick: (Product) -> Unit
    ) : RecyclerView.ViewHolder(binding.root) {

        fun bind(product: Product) {
            binding.tvProductName.text = product.name
            binding.tvProductPrice.text = binding.root.context.getString(
                R.string.currency_format,
                product.price
            )
            binding.ivProduct.load(product.imageUrl) {
                crossfade(true)
                placeholder(product.imageResId)
                error(product.imageResId)
            }

            val defaultElevation = binding.root.resources.getDimension(R.dimen.product_card_elevation)
            val pressedElevation = binding.root.resources.getDimension(R.dimen.product_card_elevation_pressed)
            binding.root.cardElevation = defaultElevation

            binding.root.setOnClickListener {
                binding.root.animate().translationZ(pressedElevation).setDuration(70L).withEndAction {
                    binding.root.animate().translationZ(defaultElevation).setDuration(140L).start()
                }.start()
                onProductClick(product)
            }
        }
    }

    override fun onCreateViewHolder(parent: ViewGroup, viewType: Int): ProductViewHolder {
        val binding = ItemProductBinding.inflate(LayoutInflater.from(parent.context), parent, false)
        return ProductViewHolder(binding, onProductClick)
    }

    private object DiffCallback : DiffUtil.ItemCallback<Product>() {
        override fun areItemsTheSame(oldItem: Product, newItem: Product): Boolean {
            return oldItem.id == newItem.id
        }

        override fun areContentsTheSame(oldItem: Product, newItem: Product): Boolean {
            return oldItem == newItem
        }
    }
}
